(function(){var o=new IntersectionObserver(function(e,t){e.forEach(function(e){if(e.isIntersecting){var t=e.target,n=t.dataset.backgroundImage;if(n){t.style.backgroundImage='url('+n+')';t.removeAttribute('data-background-image');o.unobserve(t)}}})},{rootMargin:'300px'});document.querySelectorAll('[data-background-image]').forEach(function(e){o.observe(e)})})();
